import sys,json,math

MAXREQ=32

def send(req):
    try:
        sys.stdout.write(json.dumps(req,separators=(',',':'))+'\n')
        sys.stdout.flush()
        line=sys.stdin.readline()
        if not line:
            return None
        r=json.loads(line)
        return r if isinstance(r,dict) else None
    except Exception:
        return None

def num(v,d=0.0):
    if isinstance(v,(int,float)) and not isinstance(v,bool) and v==v:
        return float(v)
    return d

MC={'wood':1.0,'rubber':2.0}

def build(r,speed,L,wm,walls):
    h=0.2
    xf=-r-0.05
    xr=xf-(L-0.2)
    if xr-r<-5.95:
        return None,0.0
    right=xf+0.1
    cx=right-L/2.0
    dy=r+0.05
    top=dy+h/2.0
    bodies=[{'shape':'rect','id':'deck','x':round(cx,4),'y':round(dy,4),'w':round(L,4),'h':h,'angle':0.0,'material':'wood'}]
    joints=[]
    cost=L*h
    for i,xw in enumerate((xr,xf)):
        bodies.append({'shape':'circle','id':'w%d'%i,'x':round(xw,4),'y':round(r,4),'r':r,'material':wm})
        joints.append({'a':'deck','b':'w%d'%i,'kind':'hinge','x':round(xw,4),'y':round(r,4),'motor_speed':speed})
        cost+=math.pi*r*r*MC[wm]
    if walls:
        wh=0.5
        for i,sx in enumerate((-0.3,0.3)):
            wx=cx+sx
            bodies.append({'shape':'rect','id':'k%d'%i,'x':round(wx,4),'y':round(top+wh/2.0-0.01,4),'w':0.1,'h':wh,'angle':0.0,'material':'wood'})
            joints.append({'a':'deck','b':'k%d'%i,'kind':'weld','x':round(wx,4),'y':round(top-0.01+0.02,4)})
            cost+=0.1*wh
    return {'language':1,'payload_on':'deck','bodies':bodies,'joints':joints},cost

def difficulty(w):
    if not isinstance(w,dict):
        return 0.0
    d=0.0
    srcs=[w]
    for k in ('params','parameters','drawn'):
        if isinstance(w.get(k),dict):
            srcs.append(w[k])
    for s in srcs:
        d+=num(s.get('bump_height'))*5.0
        p=s.get('pushes')
        if isinstance(p,list):
            d+=len(p)
        else:
            d+=num(p)
    return d

def main():
    rep=send({'op':'instances'})
    insts=[]
    remaining=0.0
    if rep and rep.get('ok'):
        insts=[i for i in (rep.get('instances') or []) if isinstance(i,dict) and i.get('id')]
        remaining=num(rep.get('remaining_steps'))
    default,_=build(0.7,-6.0,3.0,'rubber',True)
    if not insts:
        send({'op':'submit','design':default})
        return
    budget=None
    for i in insts:
        w=i.get('world') if isinstance(i.get('world'),dict) else {}
        rl=w.get('rules') if isinstance(w.get('rules'),dict) else {}
        b=rl.get('budget')
        if isinstance(b,(int,float)) and not isinstance(b,bool):
            budget=b if budget is None else min(budget,b)
    insts=sorted(insts,key=lambda i:-difficulty(i.get('world')))
    n=len(insts)
    pool=[]
    for r in (0.5,0.8):
        for sp in (-4.0,-7.0,-10.0):
            for walls in (True,False):
                for wm in ('rubber','wood'):
                    for L in (2.4,3.4):
                        d,c=build(r,sp,L,wm,walls)
                        if d is None:
                            continue
                        pool.append((c,d))
    ok=[x for x in pool if budget is None or x[0]<=budget]
    if not ok:
        ok=sorted(pool,key=lambda x:x[0])[:1] or [(0.0,default)]
    # deterministic shuffle
    s=12345
    idx=list(range(len(ok)))
    for k in range(len(idx)-1,0,-1):
        s=(s*1103515245+12345)%2147483648
        j=s%(k+1)
        idx[k],idx[j]=idx[j],idx[k]
    cands=[ok[k][1] for k in idx]
    maxms=max(num(i.get('max_steps'),2400) for i in insts)
    cap=MAXREQ
    if remaining>0:
        cap=min(cap,int(remaining//max(maxms,1.0)))
    cap=max(cap,0)
    k1=min(len(cands),max(1,cap//2),10)
    cands=cands[:k1]
    stats=[{'tested':{},'succ':0,'prog':0.0} for _ in cands]
    st={'n':0,'stop':False,'rem':remaining}
    def run(ci,ii):
        inst=insts[ii]
        ms=num(inst.get('max_steps'),2400)
        if st['n']>=MAXREQ or st['rem']<ms:
            st['stop']=True
            return
        st['n']+=1
        r=send({'op':'experiment','instance':inst.get('id'),'design':cands[ci]})
        if not r or not r.get('ok'):
            st['stop']=True
            return
        rs=r.get('remaining_steps')
        if isinstance(rs,(int,float)) and not isinstance(rs,bool):
            st['rem']=float(rs)
        else:
            st['rem']-=num(r.get('steps'))
        oc=r.get('outcome')
        if oc=='unknown':
            st['stop']=True
        succ=False
        prog=0.0
        if oc=='scored':
            m=r.get('metrics')
            if isinstance(m,dict):
                succ=m.get('success') is True
                prog=num(m.get('progress'))
        S=stats[ci]
        S['tested'][ii]=(succ,prog)
        S['succ']+=1 if succ else 0
        S['prog']+=prog
    def est(S):
        t=len(S['tested'])
        return ((S['succ']+0.3)/(t+1.0), S['prog']/t if t else 0.0)
    # stage 1: spread candidates across instances
    for ci in range(len(cands)):
        if st['stop']:
            break
        run(ci,ci%n)
    # stage 2: adaptively extend best candidates to untested instances
    while not st['stop'] and st['n']<MAXREQ:
        best=None
        bk=None
        for ci,S in enumerate(stats):
            if len(S['tested'])>=n or len(S['tested'])==0:
                continue
            k=est(S)
            if bk is None or k>bk:
                bk=k
                best=ci
        if best is None:
            break
        nxt=None
        for ii in range(n):
            if ii not in stats[best]['tested']:
                nxt=ii
                break
        if nxt is None:
            break
        run(best,nxt)
    bi=None
    bk=None
    for ci,S in enumerate(stats):
        if not S['tested']:
            continue
        k=est(S)
        if bk is None or k>bk:
            bk=k
            bi=ci
    final=cands[bi] if bi is not None else (cands[0] if cands else default)
    send({'op':'submit','design':final})

try:
    main()
except Exception:
    pass
sys.exit(0)
